        {
          "type": "formula",
          "as": "month_index",
          "expr": "indexOf(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], split(datum.month_label, ' ')[0])"
        },
        {
          "type": "stack",
          "groupby": [
            "month_index"
          ],
          "field": "donation_kusd",
          "sort": {
            "field": "channel_name"
          },
          "as": [
            "stack_start",
            "stack_end"
          ]
        }
      ]
    },
    {
      "name": "labels",
      "source": "source",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "month_label",
            "month_index"
          ]
        },
        {
          "type": "formula",
          "as": "angle_rad",
          "expr": "(datum.month_index + 0.5) * (2 * PI / 12)"
        },
        {
          "type": "formula",
          "as": "label_radius",
          "expr": 220
        },
        {
          "type": "formula",
          "as": "x",
          "expr": "width/2 + datum.label_radius * sin(datum.angle_rad)"
        },
        {
          "type": "formula",
          "as": "y",
          "expr": "height/2 - datum.label_radius * cos(datum.angle_rad)"
        }
      ]
    }
  ],
