    {
      "name": "theta",
      "type": "quantitative",
      "domain": [
        0,
        12
      ],
      "range": [
        0,
        6.28318530718
      ]
    },
    {
      "name": "radius",
      "type": "quantitative",
      "domain": {
        "data": "source",
        "field": "stack_end",
        "sort": "desc"
      },
      "range": [
        0,
        200
      ],
      "nice": true
    },
    {
      "name": "color",
      "type": "ordinal",
      "domain": [
        "Web",
        "Mobile",
        "Events"
      ],
      "range": [
        "#4c78a8",
        "#f58518",
        "#54a24b"
      ]
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "signal": "width/2"
          },
          "y": {
            "signal": "height/2"
          },
          "startAngle": {
            "scale": "theta",
            "field": "month_index"
          },
          "endAngle": {
            "scale": "theta",
            "field": "month_index",
            "offset": 1
          },
          "innerRadius": {
            "scale": "radius",
            "field": "stack_start"
          },
          "outerRadius": {
            "scale": "radius",
            "field": "stack_end"
          },
          "fill": {
            "scale": "color",
            "field": "channel_name"
          },
          "stroke": {
            "value": "#ffffff"
          },
          "strokeWidth": {
            "value": 1
          }
        },
        "update": {
          "fillOpacity": {
            "value": 0.8
          }
        },
        "hover": {
          "fillOpacity": {
            "value": 1
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "labels"
      },
      "encode": {
        "enter": {
          "x": {
            "field": "x"
          },
          "y": {
            "field": "y"
          },
          "text": {
            "field": "month_label"
          },
          "fill": {
            "value": "#000000"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          }
        }
      }
    }
  ],
  "legends": [
    {
      "fill": "color",
      "title": "Channel",
      "orient": "bottom-right",
      "labelColor": "#000000",
      "titleColor": "#000000"
    }
  ]
}

